import re,time,glob,os
t=str(int(time.time())); ch=[];nomc=[]
for fn in sorted(glob.glob('*.html')):
    if fn=='chat.html' or '.main.' in fn or '.bak' in fn: continue
    s=open(fn,encoding='utf-8').read()
    has='nox-minichat.js' in s
    if not has:
        nomc.append(fn)
        if '</body>' not in s: continue
        has=True; add='<script src="./nox-minichat.js" defer></script>\n'
    else: add=''
    if 'nox-mini-s1.js' in s and not add: continue
    open(fn+'.bak_s1_mini','w',encoding='utf-8').write(s)
    if 'nox-mini-s1.js' not in s:
        add+='<link rel="stylesheet" href="./nox-mini-s1.css?v='+t+'">\n<script src="./nox-ghost.js?v='+t+'" defer></script>\n<script src="./nox-mini-s1.js?v='+t+'" defer></script>\n'
        s=s.replace('</body>',add+'</body>',1)
    open(fn,'w',encoding='utf-8').write(s); ch.append(fn)
print('WITHOUT_MINICHAT',nomc); print('CHANGED',len(ch))
for n in ['map','book-reader','notifications','benchmark','nexus','creative','finance','pdf']:
    print(n, os.path.exists(n+'.html'))
c=open('chat.html',encoding='utf-8').read()
c=re.sub(r'(nox-chat-rq\.js|nox-chat-5\.js|nox-ghost\.js)\?v=[0-9]*',lambda m:m.group(1)+'?v='+t,c); open('chat.html','w',encoding='utf-8').write(c)
open('qa/rework/chat.fixed','a',encoding='utf-8').write('\nS1: мини-чат: nox-mini-s1.js (контекст страницы: заголовки, данные, выделение; ghost; «Ответить» с цитатой в тексте), подключён на всех страницах с мини-чатом; страницы без него получили nox-minichat.js. Чат: «Без памяти» через /svc/nox-living/incognito, meta из /svc/nox-living/meta, цитата вставляется в текст сообщения, пины заготовок через /svc/advisors/pin|unpin|pins.\n')
print('w29 ok')
